<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { ref, computed } from 'vue';
import { CopyIcon, CheckIcon, DownloadIcon, ExternalLinkIcon } from 'lucide-vue-next';

const detectOS = () => {
  if (typeof window === 'undefined' || !window.navigator) return 'windows';
  const platform = (window.navigator.platform || '').toLowerCase();
  const ua = (window.navigator.userAgent || '').toLowerCase();
  if (platform.includes('mac') || ua.includes('mac')) return 'mac';
  if (platform.includes('linux') || ua.includes('linux')) return 'linux';
  return 'windows';
};

const activeOs = ref<'windows' | 'mac' | 'linux'>(detectOS());
const activeServer = ref<'ollama' | 'llama-server'>('ollama');
const copiedCommand = ref<string | null>(null);

const isFileProtocol = typeof window !== 'undefined' && window.location.protocol === 'file:';

const ollamaServeCommand = computed(() => {
  const base = 'ollama serve';
  if (isFileProtocol) {
    // Show the environment variable for CORS when on file://
    switch (activeOs.value) {
    case 'windows':
      return '$env:OLLAMA_ORIGINS="*"; ollama serve';
    case 'mac':
      return `\
brew services stop ollama
OLLAMA_ORIGINS="*" ollama serve`;
    case 'linux':
      return 'OLLAMA_ORIGINS="*" ollama serve';
    default: {
      const _ex: never = activeOs.value;
      throw new Error(`Unhandled OS: ${_ex}`);
    }
    }
  }
  return base;
});

const copyToClipboard = async ({ text, id }: { text: string, id: string }) => {
  await navigator.clipboard.writeText(text);
  copiedCommand.value = id;
  setTimeout(() => {
    if (copiedCommand.value === id) copiedCommand.value = null;
  }, 2000);
};

interface GuideStep {
  install: string,
  downloadUrl?: string,
  installCommand?: string,
  serveCommand?: string,
  runCommand: string,
}

type Guides = {
  ollama: Record<'windows' | 'mac' | 'linux', GuideStep>,
  'llama-server': { all: GuideStep },
};

const guides = computed<Guides | undefined>(() => {
  const windowsInstall = lazyStrings.ServerSetupGuide__download_the_installer_from_the_official_website();
  const macInstall = lazyStrings.ServerSetupGuide__install_using_homebrew();
  const linuxInstall = lazyStrings.ServerSetupGuide__run_the_installation_script();
  const llamaServerInstall = lazyStrings.ServerSetupGuide__download_the_latest_binary_or_build_from_source();
  if (
    windowsInstall === undefined ||
    macInstall === undefined ||
    linuxInstall === undefined ||
    llamaServerInstall === undefined
  ) return undefined;

  return {
    ollama: {
      windows: {
        install: windowsInstall,
        downloadUrl: 'https://ollama.com/download/windows',
        serveCommand: 'ollama serve',
        runCommand: 'ollama run gemma3n:e2b',
      },
      mac: {
        install: macInstall,
        installCommand: 'brew install ollama',
        serveCommand: 'ollama serve',
        runCommand: 'ollama run gemma3n:e2b',
      },
      linux: {
        install: linuxInstall,
        installCommand: 'curl -fsSL https://ollama.com/install.sh | sh',
        serveCommand: 'ollama serve',
        runCommand: 'ollama run gemma3n:e2b',
      },
    },
    'llama-server': {
      all: {
        install: llamaServerInstall,
        downloadUrl: 'https://github.com/ggerganov/llama.cpp/releases',
        runCommand: './llama-server -hf ggml-org/gemma-3n-E2B-it-GGUF',
      },
    },
  };
});


defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
